test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = overdueInvoices([issued.value], '2026-11-06');
